struct Employee { virtual ~Employee() = default; std::string name; };
struct Engineer : Employee { std::string language; };
struct Manager  : Employee { int reports = 0; };

std::unique_ptr<Employee> from_row(const Row& r) {   // r.type is the discriminator
    if (r.type == "engineer") { auto e = std::make_unique<Engineer>(); e->language = r.language; return e; }
    if (r.type == "manager")  { auto m = std::make_unique<Manager>();  m->reports  = r.reports;  return m; }
    throw std::runtime_error("unknown discriminator: " + r.type);
}

using Record = std::variant<Employee, Engineer, Manager>;

Record from_row(const Row& r) {
    if (r.type == "engineer") return Engineer{.name = r.name, .language = r.language};
    if (r.type == "manager")  return Manager{.name = r.name, .reports = r.reports};
    throw std::runtime_error("unknown discriminator: " + r.type);
}

std::string label(const Record& rec) {
    return std::visit([](const auto& e) { return e.describe(); }, rec);
}
